import { queryOptions } from "@tanstack/react-query";
import {
  listCollectionsServerFn,
  getCollectionPageServerFn,
  getCollectionSchemaServerFn,
  getCollectionItemCountsServerFn,
} from "./collections-helpers";
import { listEnvironmentsServerFn } from "./environment-helpers";
import { listAssetsServerFn } from "./assets-helpers";
import { listProjectsServerFn, getProjectServerFn } from "./projects-helpers";
import { getAnalyticsOverviewServerFn } from "./analytics-helpers";
import {
  getActiveOrganization,
  listAdminUsers,
  listPendingInvitations,
  listApiKeysServerFn,
  listOrganizations,
} from "./auth-helpers";
import type { DateRange } from "@/db/queries/analytics";

// ── Stale time presets ──────────────────────────────────────
// Stable data that rarely changes within a session.
const STALE_LONG = 5 * 60_000; // 5 minutes
// Data that changes occasionally (collection lists, invites, keys).
const STALE_MEDIUM = 2 * 60_000; // 2 minutes
// Actively-edited data (items, assets, analytics).
const STALE_SHORT = 30_000; // 30 seconds

// ── Query keys ──────────────────────────────────────────────

export const queryKeys = {
  organization: () => ["organization"] as const,
  organizations: () => ["organizations"] as const,
  projects: () => ["projects"] as const,
  project: (id: string) => ["project", id] as const,
  collections: (page: number, limit: number) =>
    ["collections", { page, limit }] as const,
  collectionPage: (slug: string, page: number, limit: number, projectId?: string) =>
    ["collection-page", slug, { page, limit, projectId }] as const,
  collectionSchema: (slug: string) => ["collection-schema", slug] as const,
  collectionItemCounts: (collectionIds: string[]) =>
    ["collection-item-counts", collectionIds] as const,
  team: () => ["team"] as const,
  invites: () => ["invites"] as const,
  apiKeys: () => ["api-keys"] as const,
  analytics: (projectId: string, range: DateRange) =>
    ["analytics", { projectId, range }] as const,
  assets: (page: number, limit: number, projectId?: string, status?: "pending" | "active") =>
    ["assets", { page, limit, projectId, status }] as const,
  environments: (projectId: string) => ["environments", projectId] as const,
};

// ── Query options factories ─────────────────────────────────

export function organizationQueryOptions() {
  return queryOptions({
    queryKey: queryKeys.organization(),
    queryFn: () => getActiveOrganization(),
    staleTime: STALE_LONG,
  });
}

export function organizationsQueryOptions() {
  return queryOptions({
    queryKey: queryKeys.organizations(),
    queryFn: () => listOrganizations(),
    staleTime: STALE_LONG,
  });
}

export function projectsQueryOptions() {
  return queryOptions({
    queryKey: queryKeys.projects(),
    queryFn: () => listProjectsServerFn(),
    staleTime: STALE_LONG,
  });
}

export function projectQueryOptions(projectId: string) {
  return queryOptions({
    queryKey: queryKeys.project(projectId),
    queryFn: () => getProjectServerFn({ data: { id: projectId } }),
    staleTime: STALE_LONG,
    enabled: !!projectId,
  });
}

export function collectionsQueryOptions(page = 1, limit = 24, projectId?: string) {
  return queryOptions({
    queryKey: [...queryKeys.collections(page, limit), { projectId }] as const,
    queryFn: () => listCollectionsServerFn({ data: { page, limit, projectId } }),
    staleTime: STALE_MEDIUM,
  });
}

export function collectionPageQueryOptions(
  slug: string,
  page = 1,
  limit = 10,
  projectId?: string,
  env?: string,
) {
  return queryOptions({
    queryKey: [...queryKeys.collectionPage(slug, page, limit, projectId), { env }] as const,
    queryFn: () => getCollectionPageServerFn({ data: { slug, page, limit, projectId, env } }),
    staleTime: STALE_SHORT,
  });
}

export function collectionSchemaQueryOptions(slug: string, projectId?: string) {
  return queryOptions({
    queryKey: [...queryKeys.collectionSchema(slug), { projectId }],
    queryFn: () => getCollectionSchemaServerFn({ data: { slug, projectId } }),
    staleTime: STALE_LONG,
  });
}

export function collectionItemCountsQueryOptions(collectionIds: string[]) {
  return queryOptions({
    queryKey: queryKeys.collectionItemCounts(collectionIds),
    queryFn: () => getCollectionItemCountsServerFn({ data: { collectionIds } }),
    staleTime: STALE_SHORT,
    enabled: collectionIds.length > 0,
  });
}

export function teamQueryOptions(page = 1, limit = 25) {
  return queryOptions({
    queryKey: [...queryKeys.team(), { page, limit }] as const,
    queryFn: () => listAdminUsers({ data: { page, limit } }),
    staleTime: STALE_LONG,
  });
}

export function invitesQueryOptions(page = 1, limit = 25) {
  return queryOptions({
    queryKey: [...queryKeys.invites(), { page, limit }] as const,
    queryFn: () => listPendingInvitations({ data: { page, limit } }),
    staleTime: STALE_MEDIUM,
  });
}

export function apiKeysQueryOptions(page = 1, limit = 25) {
  return queryOptions({
    queryKey: [...queryKeys.apiKeys(), { page, limit }] as const,
    queryFn: () => listApiKeysServerFn({ data: { page, limit } }),
    staleTime: STALE_MEDIUM,
  });
}

export function analyticsQueryOptions(projectId: string, range: DateRange) {
  return queryOptions({
    queryKey: queryKeys.analytics(projectId, range),
    queryFn: () =>
      getAnalyticsOverviewServerFn({ data: { projectId, range } }),
    staleTime: STALE_SHORT,
    enabled: !!projectId,
  });
}

export function environmentsQueryOptions(projectId: string) {
  return queryOptions({
    queryKey: queryKeys.environments(projectId),
    queryFn: () => listEnvironmentsServerFn({ data: { projectId } }),
    staleTime: STALE_MEDIUM,
    enabled: !!projectId,
  });
}

export function assetsQueryOptions(
  page = 1,
  limit = 24,
  projectId?: string,
  status?: "pending" | "active",
) {
  return queryOptions({
    queryKey: queryKeys.assets(page, limit, projectId, status),
    queryFn: () => listAssetsServerFn({ data: { page, limit, projectId, status } }),
    staleTime: STALE_SHORT,
  });
}

import { and, asc, eq } from "drizzle-orm";
import { nanoid } from "nanoid";
import { db } from "@/db";
import { projects, type ApiAccessType } from "@/db/schema/projects";
import { createEnvironment } from "./environments";

export type CreateProjectInput = {
  organizationId: string;
  name: string;
  slug: string;
  isDefault?: boolean;
};

export async function listProjects(organizationId: string) {
  return db.query.projects.findMany({
    where: eq(projects.organizationId, organizationId),
    orderBy: [asc(projects.createdAt)],
  });
}

export async function getProjectById(id: string, organizationId?: string) {
  return db.query.projects.findFirst({
    where: organizationId
      ? and(eq(projects.id, id), eq(projects.organizationId, organizationId))
      : eq(projects.id, id),
  });
}

export async function getDefaultProject(organizationId: string) {
  const items = await listProjects(organizationId);
  return items.find((project) => project.metadata?.isDefault) ?? items[0] ?? null;
}

export async function updateProject(
  id: string,
  organizationId: string,
  data: { name?: string; slug?: string; apiAccess?: { type: ApiAccessType; allowedDomains?: string[] } },
) {
  await db
    .update(projects)
    .set({
      ...(data.name !== undefined ? { name: data.name } : {}),
      ...(data.slug !== undefined ? { slug: data.slug } : {}),
      ...(data.apiAccess !== undefined ? { apiAccess: data.apiAccess } : {}),
      updatedAt: new Date().toISOString(),
    })
    .where(and(eq(projects.id, id), eq(projects.organizationId, organizationId)));

  return getProjectById(id, organizationId);
}

export async function deleteProject(id: string, organizationId: string) {
  const project = await getProjectById(id, organizationId);

  if (!project) return null;
  if (project.metadata?.isDefault) return null;

  await db
    .delete(projects)
    .where(and(eq(projects.id, id), eq(projects.organizationId, organizationId)));

  return { success: true };
}

export async function createProject(input: CreateProjectInput) {
  const id = nanoid();
  const now = new Date().toISOString();

  await db.insert(projects).values({
    id,
    organizationId: input.organizationId,
    name: input.name,
    slug: input.slug,
    createdAt: now,
    updatedAt: now,
    metadata: input.isDefault ? { isDefault: true } : {},
  });

  // Seed a default production environment for the new project
  await createEnvironment({
    projectId: id,
    name: "Production",
    slug: "production",
    isProduction: true,
  });

  return getProjectById(id, input.organizationId);
}

import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import { apiKey } from "@better-auth/api-key";
import { betterAuth } from "better-auth";
import { tanstackStartCookies } from "better-auth/tanstack-start";
import { admin, organization, testUtils } from "better-auth/plugins";
import { db } from "@/db";
import * as schema from "@/db/schema";
import { sendEmail, sendInviteEmail } from "@/lib/email";
import {
  inviteEmailTemplate,
  verificationEmailTemplate,
} from "@/lib/email/templates";



import { env } from "@/lib/env";
import {
  ac,
  adminRole,
  memberRole,
  ownerRole,
  reviewer,
} from "@/lib/permissions";


export const auth = betterAuth({
  database: drizzleAdapter(db, {
    provider: "sqlite",
    usePlural: true,
    schema,
  }),
  secret: env.AUTH_SECRET,
  baseURL: env.APP_URL,
  emailAndPassword: {
    enabled: true,
  },
  emailVerification: {
    sendOnSignUp: true,
    async sendVerificationEmail({ user, url }) {
      const template = verificationEmailTemplate({ verificationUrl: url });

      void sendEmail({
        to: user.email,
        subject: template.subject,
        html: template.html,
      });
    },
  },
  plugins: [
    admin({
      ac,
      defaultRole: "admin",
      roles: {
        admin: adminRole,
        reviewer,
        user: memberRole,
