    }),
    apiKey({
      references: "organization",
      defaultPrefix: "mcms_",
      requireName: true,
      enableMetadata: true,
      keyExpiration: {
        defaultExpiresIn: 60 * 60 * 24 * 30,
      },
    }),
    ...(process.env.ENABLE_TEST_UTILS === "true" ? [testUtils()] : []),
    tanstackStartCookies(),
  ],
});

import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { authClient } from "@/lib/auth-client";
import { acceptInvitationAction, getInvitationById } from "@/lib/auth-helpers";
import { AlertCircle, LogIn, LogOut, UserPlus } from "lucide-react";

export const Route = createFileRoute("/invite/$token")({
  loader: ({ params }) => getInvitationById({ data: { id: params.token } }),
  component: InvitePage,
});

function InvitePage() {
  const { token } = Route.useParams();
  const invitation = Route.useLoaderData();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const hasSession = invitation?.hasSession === true;
  const emailMatchesSession = invitation?.emailMatchesSession === true;

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPending(true);
    setError(null);

    const signUp = await authClient.signUp.email({
      name,
      email,
      password,
    });

    if (signUp.error) {
      setPending(false);
      setError(signUp.error.message ?? "Unable to create account.");
      return;
    }

    const accepted = await acceptInvitationAction({ data: { invitationId: token } });

    setPending(false);

    if (!accepted) {
      setError("Unable to accept invitation.");
      return;
    }

    await queryClient.invalidateQueries({ queryKey: ["invites"] });
    await queryClient.invalidateQueries({ queryKey: ["team"] });
    await navigate({ to: "/dashboard", search: { projectId: undefined } });
  }

  async function handleAcceptDirectly() {
    setPending(true);
    setError(null);

    try {
      const accepted = await acceptInvitationAction({
        data: { invitationId: token },
      });

      if (!accepted) {
        setError("Unable to accept invitation.");
        return;
      }

      await queryClient.invalidateQueries({ queryKey: ["invites"] });
      await queryClient.invalidateQueries({ queryKey: ["team"] });
      await navigate({ to: "/dashboard", search: { projectId: undefined } });
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Unable to accept invitation.",
      );
    } finally {
      setPending(false);
    }
  }

  return (
    <div className="flex min-h-svh items-center justify-center bg-stone-50 px-4 py-10 dark:bg-stone-950">
      <div className="w-full max-w-lg rounded-3xl border border-stone-200 bg-white p-8 shadow-sm dark:border-stone-800 dark:bg-stone-900">
        <p className="text-xs uppercase tracking-[0.24em] text-stone-500 dark:text-stone-400">
          Invite
        </p>
        <h1 className="mt-2 text-3xl font-semibold tracking-tight dark:text-stone-100">
          Accept your invitation
        </h1>
        <p className="mt-3 text-sm text-stone-600 dark:text-stone-400">
          Join {invitation?.organizationName ?? "the invited organization"} as{" "}
          {invitation?.role ?? "a member"}.
        </p>

        {hasSession && !emailMatchesSession ? (
          <div className="mt-8 space-y-4">
            <div className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800 dark:border-amber-900/60 dark:bg-amber-950/40 dark:text-amber-200">
              <div className="flex items-start gap-2">
                <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
                <p>
                  This signed-in account cannot accept the invite. Sign out and continue with the invited account.
                </p>
              </div>
            </div>
            {error ? <p className="text-sm text-red-600 dark:text-red-400">{error}</p> : null}
            <div className="grid gap-3 sm:grid-cols-2">
              <button
                type="button"
                onClick={() => {
                  void authClient.signOut({
                    fetchOptions: {
                      onSuccess: () => {
                        void navigate({ to: "/login", search: { redirect: `/invite/${token}` } });
                      },
                    },
                  });
                }}
                className="inline-flex items-center justify-center gap-2 rounded-2xl border border-stone-300 px-4 py-3 text-sm font-medium transition hover:bg-stone-50 dark:border-stone-700 dark:hover:bg-stone-800"
              >
                <LogOut className="h-4 w-4" />
                Sign out
              </button>
              <button
                type="button"
                onClick={() =>
                  void navigate({ to: "/login", search: { redirect: `/invite/${token}` } })
                }
                className="inline-flex items-center justify-center gap-2 rounded-2xl bg-stone-900 px-4 py-3 text-sm font-medium text-white transition hover:bg-stone-700 dark:bg-white dark:text-stone-900 dark:hover:bg-stone-200"
              >
                <LogIn className="h-4 w-4" />
                Use another account
              </button>
            </div>
          </div>
        ) : emailMatchesSession ? (
          <div className="mt-8 space-y-4">
            <div className="rounded-2xl border border-stone-200 bg-stone-50 px-4 py-3 text-sm text-stone-600 dark:border-stone-800 dark:bg-stone-800/60 dark:text-stone-300">
              Signed in as {invitation?.currentUserEmail}. You can join this workspace now.
            </div>
            {error ? <p className="text-sm text-red-600 dark:text-red-400">{error}</p> : null}
            <button
              type="button"
              disabled={pending}
              onClick={() => void handleAcceptDirectly()}
              className="w-full rounded-2xl bg-stone-900 px-4 py-3 text-sm font-medium text-white transition hover:bg-stone-700 disabled:cursor-not-allowed disabled:opacity-60 dark:bg-white dark:text-stone-900 dark:hover:bg-stone-200"
            >
              {pending ? "Joining workspace..." : "Join workspace"}
            </button>
          </div>
        ) : (
          <>
            <div className="mt-8 rounded-2xl border border-stone-200 bg-stone-50 px-4 py-3 text-sm text-stone-600 dark:border-stone-800 dark:bg-stone-800/60 dark:text-stone-300">
              Sign in with your invited account, or create it first, to join this workspace.
            </div>
            <div className="mt-4 grid gap-3 sm:grid-cols-2">
              <button
                type="button"
                onClick={() =>
                  void navigate({ to: "/login", search: { redirect: `/invite/${token}` } })
                }
                className="inline-flex items-center justify-center gap-2 rounded-2xl border border-stone-300 px-4 py-3 text-sm font-medium transition hover:bg-stone-50 dark:border-stone-700 dark:hover:bg-stone-800"
              >
                <LogIn className="h-4 w-4" />
                Sign in
              </button>
              <button
                type="button"
                onClick={() =>
                  void navigate({ to: "/signup", search: { redirect: `/invite/${token}` } })
                }
                className="inline-flex items-center justify-center gap-2 rounded-2xl bg-stone-900 px-4 py-3 text-sm font-medium text-white transition hover:bg-stone-700 dark:bg-white dark:text-stone-900 dark:hover:bg-stone-200"
              >
                <UserPlus className="h-4 w-4" />
                Create account
              </button>
            </div>

            <form className="mt-8 space-y-4" onSubmit={handleSubmit}>
              <Field
                label="Full name"
                type="text"
                value={name}
                onChange={setName}
              />
              <Field
                label="Email"
                type="email"
                value={email}
                onChange={setEmail}
              />
              <Field
                label="Password"
                type="password"
                value={password}
                onChange={setPassword}
              />
              {error ? <p className="text-sm text-red-600 dark:text-red-400">{error}</p> : null}
              <button
                type="submit"
                disabled={pending}
                className="w-full rounded-2xl bg-stone-900 px-4 py-3 text-sm font-medium text-white transition hover:bg-stone-700 disabled:cursor-not-allowed disabled:opacity-60 dark:bg-white dark:text-stone-900 dark:hover:bg-stone-200"
              >
                {pending ? "Creating account..." : "Create account to join"}
              </button>
            </form>
          </>
        )}
      </div>
    </div>
  );
}

function Field(props: {
  label: string;
  type: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <label className="block space-y-2">
      <span className="text-sm font-medium text-stone-700 dark:text-stone-300">{props.label}</span>
      <input
        type={props.type}
        value={props.value}
        onChange={(event) => props.onChange(event.target.value)}
        className="w-full rounded-2xl border border-stone-300 bg-white px-4 py-3 text-sm outline-none transition focus:border-stone-900 dark:border-stone-700 dark:bg-stone-800 dark:text-stone-100 dark:focus:border-stone-500"
        required
      />
    </label>
  );
}

import { createServerFn } from "@tanstack/react-start";
import {
  captureServerError,
  captureServerEvent,
  createAnonymousServerIdentity,
} from "@/lib/posthog";

export const getProjectServerFn = createServerFn({ method: "GET" })
  .validator((data: { id: string }) => data)
  .handler(async ({ data, ...ctx }) => {
    try {
      const { requireActiveOrganizationId } = await import("./auth-helpers");
      const { getProjectById } = await import("../db/queries/projects");
      const organizationId = await requireActiveOrganizationId(ctx);

      return getProjectById(data.id, organizationId);
    } catch (error) {
      await captureServerError({
        error,
        identity: createAnonymousServerIdentity({}),
        properties: {
          area: "projects",
          operation: "get",
        },
      });
      throw error;
    }
  });

export const listProjectsServerFn = createServerFn({ method: "GET" }).handler(
  async (ctx) => {
    const { requireActiveOrganizationId } = await import("./auth-helpers");
    const { listProjects } = await import("../db/queries/projects");

    return listProjects(await requireActiveOrganizationId(ctx));
  },
);

export const createProjectServerFn = createServerFn({ method: "POST" })
  .validator((data: { name: string; slug: string }) => data)
  .handler(async ({ data, ...ctx }) => {
    let organizationId: string | undefined;

    try {
      const { requireActiveOrganizationId } = await import("./auth-helpers");
      const { createProject } = await import("../db/queries/projects");
      const { ensureProjectLimit } = await import("./demo-limits");
      organizationId = await requireActiveOrganizationId(ctx);

      await ensureProjectLimit(organizationId);

      const project = await createProject({
        organizationId,
        name: data.name,
        slug: data.slug,
      });

      if (project) {
        await captureServerEvent({
          event: "project_created",
          identity: createAnonymousServerIdentity({
            organizationId,
            projectId: project.id,
          }),
          properties: {},
        });
      }

      return project;
    } catch (error) {
      await captureServerError({
        error,
        identity: createAnonymousServerIdentity({ organizationId }),
        properties: {
          area: "projects",
          operation: "create",
        },
      });
      throw error;
    }
  });

export const updateProjectServerFn = createServerFn({ method: "POST" })
  .validator(
    (data: { id: string; name?: string; slug?: string; apiAccess?: { type: "public" | "restricted" | "none"; allowedDomains?: string[] } }) => data,
  )
  .handler(async ({ data, ...ctx }) => {
    let organizationId: string | undefined;

    try {
      const { requireActiveOrganizationId } = await import("./auth-helpers");
      const { updateProject } = await import("../db/queries/projects");
      organizationId = await requireActiveOrganizationId(ctx);

      const project = await updateProject(data.id, organizationId, {
        name: data.name,
        slug: data.slug,
        apiAccess: data.apiAccess,
      });

      if (project) {
        await captureServerEvent({
          event: "project_updated",
          identity: createAnonymousServerIdentity({
            organizationId,
            projectId: project.id,
          }),
          properties: {
            name_updated: data.name !== undefined,
            slug_updated: data.slug !== undefined,
            apiAccess_updated: data.apiAccess !== undefined,
          },
        });
      }

      return project;
    } catch (error) {
      await captureServerError({
        error,
        identity: createAnonymousServerIdentity({
          organizationId,
          projectId: data.id,
        }),
        properties: {
          area: "projects",
          operation: "update",
        },
      });
      throw error;
    }
  });

export const deleteProjectServerFn = createServerFn({ method: "POST" })
  .validator((data: { id: string }) => data)
  .handler(async ({ data, ...ctx }) => {
    let organizationId: string | undefined;

    try {
      const { requireActiveOrganizationId } = await import("./auth-helpers");
      const { deleteProject } = await import("../db/queries/projects");
      organizationId = await requireActiveOrganizationId(ctx);

      const result = await deleteProject(data.id, organizationId);

      if (result?.success) {
        await captureServerEvent({
          event: "project_deleted",
          identity: createAnonymousServerIdentity({
            organizationId,
            projectId: data.id,
          }),
          properties: {},
        });
      }

      return result;
    } catch (error) {
      await captureServerError({
        error,
        identity: createAnonymousServerIdentity({
          organizationId,
          projectId: data.id,
        }),
        properties: {
          area: "projects",
          operation: "delete",
        },
      });
      throw error;
    }
  });

