async function dump(page: import("@playwright/test").Page, tag: string) {
  const info = await page.evaluate(() => {
    const pick = (sel: string) => {
      const el = document.querySelector(sel);
      if (!el) return null;
      const cs = getComputedStyle(el);
      return { sel, bg: cs.backgroundColor, color: cs.color, cls: (el.className || "").toString().slice(0, 160) };
    };
    return {
      slots: Array.from(document.querySelectorAll('[data-slot="sidebar"],[data-slot="sidebar-container"],[data-slot="sidebar-inner"],[data-slot="sidebar-wrap"],[data-slot="sidebar-content"],[data-slot="sidebar-inset"],[data-slot="sidebar-menu"]')).map(el => {
        const cs = getComputedStyle(el);
        return { slot: el.getAttribute("data-slot"), bg: cs.backgroundColor, mobile: el.getAttribute("data-mobile"), cls: (el.className||"").toString().slice(0,120) };
      }),
      sheets: Array.from(document.querySelectorAll('[data-slot="sheet-content"],[role="dialog"]')).map(el => {
        const cs = getComputedStyle(el);
        return { slot: el.getAttribute("data-slot"), role: el.getAttribute("role"), bg: cs.backgroundColor, cls: (el.className||"").toString().slice(0,140) };
      }),
      bodyBg: getComputedStyle(document.body).backgroundColor,
      innerBg: pick("#__next") ? null : null,
    };
  });
  console.log(tag, JSON.stringify(info, null, 2));
}

