import { Link, createFileRoute } from "@tanstack/react-router";
import { useEffect, useMemo, useState, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  createCollectionServerFn,
  deleteCollectionServerFn,
} from "@/lib/collections-helpers";
import { createProjectServerFn } from "@/lib/projects-helpers";
import {
  collectionsQueryOptions,
  collectionItemCountsQueryOptions,
  organizationQueryOptions,
  projectsQueryOptions,
} from "@/lib/queries";
import { DataToolbar, type SortState } from "@workspace/ui/components/data-table";
import { Skeleton } from "@workspace/ui/components/skeleton";
import {
  Plus,
  Folder,
  X,
  Tag,
  FileText,
  Type,
  ArrowRight,
  Copy,
  FolderTree,
  MoreHorizontal,
  Pencil,
  Trash2,
} from "lucide-react";

export const Route = createFileRoute("/dashboard/")({
  validateSearch: (search: Record<string, unknown>) => ({
    projectId:
      typeof search.projectId === "string" && search.projectId.length > 0
        ? search.projectId
        : undefined,
  }),
  component: DashboardHome,
});

function DashboardHome() {
  const search = Route.useSearch();
  const queryClient = useQueryClient();
  const orgQuery = useQuery(organizationQueryOptions());
  const projectsQuery = useQuery(projectsQueryOptions());
  const organization = orgQuery.data ?? null;
  const projects = projectsQuery.data ?? [];
  const selectedProjectId = search.projectId ?? "";
  const collectionsQuery = useQuery({
    ...collectionsQueryOptions(1, 24, selectedProjectId || undefined),
    enabled: Boolean(organization) && !!selectedProjectId,
  });

  const collectionIds = collectionsQuery.data?.items.map((c) => c.id) ?? [];
  const itemCountsQuery = useQuery(
    collectionItemCountsQueryOptions(collectionIds),
  );

  const isLoading = collectionsQuery.isLoading || itemCountsQuery.isLoading;

  function invalidate() {
    void queryClient.invalidateQueries({ queryKey: ["collections"] });
    void queryClient.invalidateQueries({ queryKey: ["collection-item-counts"] });
    void queryClient.invalidateQueries({ queryKey: ["organization"] });
    void queryClient.invalidateQueries({ queryKey: ["projects"] });
  }

  const collections = collectionsQuery.data ?? {
    items: [],
    pagination: { page: 1, limit: 24, total: 0, totalPages: 1, hasMore: false },
  };
  const itemCounts = itemCountsQuery.data ?? {};

  // Client-side filter/sort state for the collections list
  const [filterQ, setFilterQ] = useState("");
  const [filterSort, setFilterSort] = useState<SortState | null>(null);

  const filteredCollections = useMemo(() => {
    let list = collections.items;
    if (filterQ) {
      const q = filterQ.toLowerCase();
      list = list.filter(
        (c: any) =>
          c.name?.toLowerCase().includes(q) ||
          c.slug?.toLowerCase().includes(q),
      );
    }
    if (filterSort) {
      list = [...list].sort((a: any, b: any) => {
        const aVal = a[filterSort.by] ?? "";
        const bVal = b[filterSort.by] ?? "";
        const cmp = String(aVal).localeCompare(String(bVal));
        return filterSort.order === "desc" ? -cmp : cmp;
      });
    }
    return list;
  }, [collections.items, filterQ, filterSort]);

  if (isLoading) {
    return <DashboardHomeSkeleton />;
  }

  if (!organization) {
    return (
      <section className="space-y-6">
        <div className="space-y-1">
          <h2 className="text-2xl font-semibold tracking-tight text-stone-900">
            Workspace required
          </h2>
          <p className="text-sm text-stone-500">
            Create a workspace from the sidebar before you create projects or collections.
          </p>
        </div>
      </section>
    );
  }

  return (
    <section className="space-y-6">
      <div className="space-y-1 text-sm text-stone-600">
        <h2 className="text-2xl font-semibold tracking-tight text-stone-900">
          {organization.name}
        </h2>
        <p className="flex items-center gap-1.5">
          <span className="text-stone-500">Slug:</span>
          <code className="rounded bg-stone-100 px-1.5 py-0.5 font-mono text-xs text-stone-700">
            {organization.slug}
          </code>
          <CopyButton value={organization.slug} />
        </p>
        <p className="flex items-center gap-1.5">
          <span className="text-stone-500">ID:</span>
          <code className="rounded bg-stone-100 px-1.5 py-0.5 font-mono text-xs text-stone-700">
            {organization.id}
          </code>
          <CopyButton value={organization.id} />
        </p>
      </div>

      <div className="flex items-center justify-between gap-4">
        <div className="space-y-1">
          <p className="text-sm text-stone-500">
            {selectedProjectId
              ? `Showing collections for ${projects.find((project) => project.id === selectedProjectId)?.name ?? "your selected project"}.`
              : "Select or create a project from the sidebar to manage collections."}
          </p>
        </div>
        <NewProjectDialog onCreated={invalidate} />
      </div>

      <div className="flex items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-semibold tracking-tight">Collections</h3>
          <p className="mt-1 text-sm text-stone-500">
            {selectedProjectId
              ? `${filteredCollections.length} collection${filteredCollections.length === 1 ? "" : "s"}`
              : "Choose a project to see its collections."}
          </p>
        </div>
        <NewCollectionDialog
          projectId={selectedProjectId}
          projectName={projects.find((project) => project.id === selectedProjectId)?.name ?? null}
          onCreated={invalidate}
        />
      </div>

      {!selectedProjectId ? (
        <div className="rounded-xl border border-dashed border-stone-300 bg-stone-50 px-6 py-14 text-center dark:border-stone-700 dark:bg-stone-900/60">
          <h3 className="text-base font-medium text-stone-900 dark:text-stone-100">
            No project selected
          </h3>
          <p className="mt-1 text-sm text-stone-500 dark:text-stone-400">
            Select a project from the sidebar, or create one to start organizing collections.
          </p>
        </div>
      ) : (
      <>
      <DataToolbar
        query={filterQ}
        onQueryChange={setFilterQ}
        refresh={{
          onRefresh: invalidate,
          isRefreshing: collectionsQuery.isFetching,
        }}
        sortColumns={[
          { id: "name", label: "Name" },
          { id: "createdAt", label: "Created" },
        ]}
        sort={filterSort}
        onSortChange={setFilterSort}
        filterPlaceholder="Filter collections…"
      />
      {/* Desktop table */}
      <div className="hidden overflow-hidden rounded-lg border border-stone-200 md:block">
        <table className="min-w-full divide-y divide-stone-200 text-sm">
          <thead className="bg-stone-50">
            <tr>
              <th className="px-4 py-3 text-left font-medium text-stone-600">
                Name
              </th>
              <th className="px-4 py-3 text-left font-medium text-stone-600">
                Slug
              </th>
              <th className="hidden px-4 py-3 text-left font-medium text-stone-600 md:table-cell">
                Items
              </th>
              <th className="hidden px-4 py-3 text-left font-medium text-stone-600 md:table-cell">
                Description
              </th>
              <th className="px-4 py-3 text-right font-medium text-stone-600">
                <span className="sr-only">Actions</span>
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-stone-100 bg-white">
            {filteredCollections.map(
              (collection: (typeof filteredCollections)[number]) => (
                <tr key={collection.id} className="hover:bg-stone-50">
                  <td className="px-4 py-3">
                    <Link
                      to="/dashboard/collections/$name"
                      params={{ name: collection.slug }}
                      search={{ page: 1, projectId: selectedProjectId || undefined, env: undefined }}
                      className="flex items-center gap-2.5 group"
                    >
                      <Folder className="h-4 w-4 shrink-0 text-stone-400" />
                      <span className="font-medium text-stone-900 group-hover:underline">
                        {collection.name}
                      </span>
                    </Link>
                  </td>
                  <td className="px-4 py-3 font-mono text-xs text-stone-500">
                    /{collection.slug}
                  </td>
                  <td className="hidden px-4 py-3 text-stone-500 md:table-cell">
                    {itemCounts[collection.id] ?? 0}
                  </td>
                  <td className="hidden px-4 py-3 text-stone-500 md:table-cell">
                    <span className="line-clamp-1">
                      {collection.description || "-"}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right">
                    <CollectionActionsMenu
                      collection={collection}
                      projectId={selectedProjectId}
                      onDeleted={invalidate}
                    />
                  </td>
                </tr>
              ),
            )}
            {!filteredCollections.length ? (
              <tr>
                <td
                  colSpan={5}
                  className="px-4 py-10 text-center text-stone-500"
                >
                  No collections yet. Create your first one to get started.
                </td>
              </tr>
            ) : null}
          </tbody>
        </table>
      </div>

      {/* Mobile cards */}
      <div className="space-y-3 md:hidden">
        {filteredCollections.length ? (
          filteredCollections.map((collection: (typeof filteredCollections)[number]) => (
            <div
              key={collection.id}
              className="rounded-lg border border-stone-200 bg-white p-4 dark:border-stone-800 dark:bg-stone-900"
            >
              <div className="flex items-start justify-between gap-2">
                <Link
                  to="/dashboard/collections/$name"
                  params={{ name: collection.slug }}
                  search={{ page: 1, projectId: selectedProjectId || undefined, env: undefined }}
                  className="flex items-center gap-2.5 min-w-0"
                >
                  <Folder className="h-4 w-4 shrink-0 text-stone-400" />
                  <span className="truncate font-medium text-stone-900 dark:text-stone-100">
                    {collection.name}
                  </span>
                </Link>
                <CollectionActionsMenu
                  collection={collection}
                  projectId={selectedProjectId}
                  onDeleted={invalidate}
                />
              </div>
              <div className="mt-2 space-y-1 text-xs text-stone-500 dark:text-stone-400">
                <p className="font-mono">/{collection.slug}</p>
                <p className="flex items-center gap-1">
                  <span className="font-medium text-stone-600 dark:text-stone-400">
                    {itemCounts[collection.id] ?? 0}
                  </span>
                  items
                </p>
                {collection.description ? (
                  <p className="line-clamp-2 text-stone-500 dark:text-stone-400">
                    {collection.description}
                  </p>
                ) : null}
              </div>
            </div>
          ))
        ) : (
          <p className="py-10 text-center text-sm text-stone-500">
            No collections yet. Create your first one to get started.
          </p>
        )}
      </div>
      </>
      )}
    </section>
  );
}

function DashboardHomeSkeleton() {
  return (
    <section className="space-y-6">
      <div className="space-y-2">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-4 w-64" />
        <Skeleton className="h-4 w-56" />
      </div>

      <div className="flex items-center justify-between gap-4">
        <div className="space-y-1">
          <Skeleton className="h-6 w-28" />
          <Skeleton className="h-4 w-24" />
        </div>
        <Skeleton className="h-9 w-36 rounded-lg" />
      </div>

      <div className="hidden overflow-hidden rounded-lg border border-stone-200 md:block">
        <table className="min-w-full divide-y divide-stone-200 text-sm">
          <thead className="bg-stone-50">
            <tr>
              <th className="px-4 py-3 text-left font-medium text-stone-600">
                Name
              </th>
              <th className="px-4 py-3 text-left font-medium text-stone-600">
                Slug
              </th>
              <th className="hidden px-4 py-3 text-left font-medium text-stone-600 md:table-cell">
