import { createServerFn } from "@tanstack/react-start";
import type { CollectionField } from "@/db/queries/collections";

export const createCollectionServerFn = createServerFn({ method: "POST" })
  .validator(
    (data: {
      projectId?: string;
      name: string;
      slug: string;
      description?: string;
      schema: CollectionField[];
    }) => data,
  )
  .handler(async ({ data, ...ctx }) => {
    const { requireActiveOrganizationId } = await import("./auth-helpers");
    const { createCollectionAction } =
      await import("../server/functions/collections");
    return createCollectionAction({
      organizationId: await requireActiveOrganizationId(ctx),
      projectId: data.projectId,
      name: data.name,
      slug: data.slug,
      description: data.description,
      schema: data.schema,
    });
  });

export const updateCollectionServerFn = createServerFn({ method: "POST" })
  .validator(
    (data: {
      id: string;
      name?: string;
      slug?: string;
      description?: string | null;
      schema?: CollectionField[];
    }) => data,
  )
  .handler(async ({ data }) => {
    const { updateCollectionAction } =
      await import("../server/functions/collections");
    return updateCollectionAction(data.id, {
      name: data.name,
      slug: data.slug,
      description: data.description,
      schema: data.schema,
    });
  });

export const listCollectionsServerFn = createServerFn({ method: "GET" })
  .validator(
    (data: { page?: number; limit?: number; projectId?: string } | undefined) =>
      data,
  )
  .handler(async ({ data, ...ctx }) => {
    const { requireActiveOrganizationId } = await import("./auth-helpers");
    const { listCollections } = await import("../db/queries/collections");
    return listCollections({
      ...data,
      organizationId: await requireActiveOrganizationId(ctx),
    });
  });

export const getCollectionSchemaServerFn = createServerFn({ method: "GET" })
  .validator((data: { slug: string; projectId?: string }) => data)
  .handler(async ({ data, ...ctx }) => {
    const { requireActiveOrganizationId } = await import("./auth-helpers");
    const { getCollectionBySlug } = await import("../db/queries/collections");
    const collection = await getCollectionBySlug(
      data.slug,
      await requireActiveOrganizationId(ctx),
      data.projectId,
    );

    if (!collection) {
      throw new Error("Collection not found");
    }

    return { collection };
  });

export const getCollectionPageServerFn = createServerFn({ method: "GET" })
  .validator(
    (data: {
      slug: string;
      page?: number;
      limit?: number;
      projectId?: string;
      env?: string;
    }) => data,
  )
  .handler(async ({ data, ...ctx }) => {
    const { requireActiveOrganizationId } = await import("./auth-helpers");
    const [{ getCollectionBySlug }, { listItems }] = await Promise.all([
      import("../db/queries/collections"),
      import("../db/queries/items"),
      import("../db/queries/environments"),
    ]);

    const organizationId = await requireActiveOrganizationId(ctx);
    const collection = await getCollectionBySlug(
      data.slug,
      organizationId,
      data.projectId,
    );

    if (!collection) {
      throw new Error("Collection not found");
    }

    // Resolve environment slug → ID
    let environmentId: string | undefined;
    if (data.projectId && data.env) {
      const { getEnvironmentBySlug, getProductionEnvironment } =
        await import("../db/queries/environments");
      const env = data.env === "production"
        ? await getProductionEnvironment(data.projectId)
        : await getEnvironmentBySlug(data.env, data.projectId);
      if (env) {
        environmentId = env.id;
      }
    }

    const items = await listItems(collection.id, {
      page: data.page,
      limit: data.limit,
      environmentId,
    });

    return { collection, items, environment: environmentId ? undefined : undefined };
  });

export const createItemServerFn = createServerFn({ method: "POST" })
  .validator(
    (data: {
      collectionId: string;
      slug: string;
      values: Record<string, string | number | boolean | null>;
      order?: number;
    }) => data,
  )
  .handler(async ({ data }) => {
    const { createItemAction } = await import("../server/functions/items");
    return createItemAction(
      data.collectionId,
      data.slug,
      data.values,
      data.order,
    );
  });

export const updateItemServerFn = createServerFn({ method: "POST" })
  .validator(
    (data: {
      id: string;
      slug: string;
      values: Record<string, string | number | boolean | null>;
    }) => data,
  )
  .handler(async ({ data }) => {
    const { updateItemAction } = await import("../server/functions/items");
    return updateItemAction(data.id, data.slug, data.values);
  });

export const deleteItemServerFn = createServerFn({ method: "POST" })
  .validator((data: { id: string; slug: string }) => data)
  .handler(async ({ data }) => {
    const { deleteItemAction } = await import("../server/functions/items");
    await deleteItemAction(data.id, data.slug);
    return { success: true };
  });

export const promoteItemsServerFn = createServerFn({ method: "POST" })
  .validator(
    (data: {
      itemIds: string[];
      productionEnvironmentId: string;
      collectionSlug: string;
    }) => data,
  )
  .handler(async ({ data }) => {
    const { promoteItemsAction } = await import("../server/functions/items");
    return promoteItemsAction(
      data.itemIds,
      data.productionEnvironmentId,
      data.collectionSlug,
    );
  });

export const duplicateItemsServerFn = createServerFn({ method: "POST" })
  .validator(
    (data: {
      itemIds: string[];
      sourceEnvironmentId: string;
      targetEnvironmentId: string;
      collectionSlug: string;
    }) => data,
  )
  .handler(async ({ data }) => {
    const { duplicateItemsAction } = await import("../server/functions/items");
    return duplicateItemsAction(
      data.itemIds,
      data.sourceEnvironmentId,
      data.targetEnvironmentId,
      data.collectionSlug,
    );
  });

export const deleteCollectionServerFn = createServerFn({ method: "POST" })
  .validator((data: { id: string; slug?: string }) => data)
  .handler(async ({ data }) => {
    const { deleteCollectionAction } =
      await import("../server/functions/collections");
    return deleteCollectionAction(data.id, data.slug);
  });

export const getCollectionItemCountsServerFn = createServerFn({ method: "GET" })
  .validator(
    (data: { collectionIds: string[] } | undefined) => data,
  )
  .handler(async ({ data }) => {
    if (!data?.collectionIds?.length) return {};
    const { countItemsByCollectionIds } = await import("../db/queries/items");
    const counts = await countItemsByCollectionIds(data.collectionIds);
    return Object.fromEntries(counts);
  });

import {
  createItem,
  deleteItem,
  duplicateItemsToEnvironment,
  listItems,
  promoteItemsToProduction,
  reorderItems,
  updateItem,
  type CollectionItemData,
} from "@/db/queries/items";
import { invalidateCollectionCache } from "@/lib/cache";
import { ensureItemLimit } from "@/lib/demo-limits";
import {
  anonymizeServerValue,
  captureServerError,
  captureServerEvent,
  createAnonymousServerIdentity,
} from "@/lib/posthog";

export async function listItemsAction(
  collectionId: string,
  input?: { page?: number; limit?: number },
) {
  return listItems(collectionId, input);
}

export async function createItemAction(
  collectionId: string,
  slug: string,
  data: CollectionItemData,
  order?: number,
) {
  const identity = createAnonymousServerIdentity({ subject: collectionId });

  try {
    await ensureItemLimit(collectionId);
    const item = await createItem(collectionId, data, { order });
    await invalidateCollectionCache(slug);

    await captureServerEvent({
      event: "item_created",
      identity,
      properties: {
        collection_slug_hash: anonymizeServerValue(slug, "collection"),
        field_count: Object.keys(data).length,
        has_explicit_order: order !== undefined,
      },
    });

    return item;
  } catch (error) {
    await captureServerError({
      error,
      identity,
      properties: {
        area: "items",
        operation: "create",
      },
    });
    throw error;
  }
}

export async function updateItemAction(
  id: string,
  slug: string,
  data: CollectionItemData,
) {
  const identity = createAnonymousServerIdentity({ subject: id });

  try {
    const item = await updateItem(id, data);
    await invalidateCollectionCache(slug);

    await captureServerEvent({
      event: "item_updated",
      identity,
      properties: {
        collection_slug_hash: anonymizeServerValue(slug, "collection"),
        field_count: Object.keys(data).length,
      },
    });

    return item;
  } catch (error) {
    await captureServerError({
      error,
      identity,
      properties: {
        area: "items",
        operation: "update",
      },
    });
    throw error;
  }
}

export async function deleteItemAction(id: string, slug: string) {
  const identity = createAnonymousServerIdentity({ subject: id });

  try {
    await deleteItem(id);
    await invalidateCollectionCache(slug);

    await captureServerEvent({
      event: "item_deleted",
      identity,
      properties: {
        collection_slug_hash: anonymizeServerValue(slug, "collection"),
      },
    });
  } catch (error) {
    await captureServerError({
      error,
      identity,
      properties: {
        area: "items",
        operation: "delete",
      },
    });
    throw error;
  }
}

/**
 * Promote items to the project's production environment.
 * Items are moved (environment_id updated) — they leave the current env.
 */
export async function promoteItemsAction(
  itemIds: string[],
  productionEnvironmentId: string,
  collectionSlug: string,
) {
  const identity = createAnonymousServerIdentity({
    subject: `promote:${productionEnvironmentId}`,
  });

  try {
    await promoteItemsToProduction(itemIds, productionEnvironmentId);
    await invalidateCollectionCache(collectionSlug, productionEnvironmentId);

    await captureServerEvent({
      event: "items_promoted",
      identity,
      properties: {
        item_count: itemIds.length,
        target_env_id: productionEnvironmentId,
        collection_slug_hash: anonymizeServerValue(collectionSlug, "collection"),
      },
    });

    return { success: true, promotedCount: itemIds.length };
  } catch (error) {
    await captureServerError({
      error,
      identity,
      properties: {
        area: "items",
        operation: "promote",
      },
    });
    throw error;
  }
}

/**
 * Duplicate items to another environment.
 * Items are copied (new IDs) — the originals remain in the source env.
 */
export async function duplicateItemsAction(
  itemIds: string[],
  sourceEnvironmentId: string,
  targetEnvironmentId: string,
  collectionSlug: string,
) {
  const identity = createAnonymousServerIdentity({
    subject: `duplicate:${sourceEnvironmentId}->${targetEnvironmentId}`,
  });

  try {
    const newIds = await duplicateItemsToEnvironment(
      itemIds,
      sourceEnvironmentId,
      targetEnvironmentId,
    );

    await invalidateCollectionCache(collectionSlug, targetEnvironmentId);
    await invalidateCollectionCache(collectionSlug, sourceEnvironmentId);

    await captureServerEvent({
      event: "items_duplicated",
      identity,
      properties: {
        item_count: itemIds.length,
        source_env_id: sourceEnvironmentId,
        target_env_id: targetEnvironmentId,
        collection_slug_hash: anonymizeServerValue(collectionSlug, "collection"),
      },
    });

    return { success: true, duplicatedCount: itemIds.length, newIds };
  } catch (error) {
    await captureServerError({
      error,
      identity,
      properties: {
        area: "items",
        operation: "duplicate",
      },
    });
    throw error;
  }
}

export async function reorderItemsAction(
  collectionId: string,
  slug: string,
  itemIds: string[],
) {
  const identity = createAnonymousServerIdentity({ subject: collectionId });

  try {
    await reorderItems(collectionId, itemIds);
    await invalidateCollectionCache(slug);

    await captureServerEvent({
      event: "items_reordered",
      identity,
      properties: {
        collection_slug_hash: anonymizeServerValue(slug, "collection"),
        item_count: itemIds.length,
      },
    });
  } catch (error) {
    await captureServerError({
      error,
      identity,
      properties: {
        area: "items",
        operation: "reorder",
      },
    });
