        chain.push({ tag: el.tagName, slot: el.getAttribute("data-slot"), cls: (el.className||"").toString().slice(0,90), bg: cs.backgroundColor });
        el = el.parentElement;
      }
      const sb = document.querySelector('[data-slot="sidebar"]');
      return { chain, sidebar: sb ? getComputedStyle(sb).backgroundColor : null,
               sidebarCls: sb ? (sb.className||"").toString() : null,
               htmlClass: document.documentElement.className };
    });
    console.log(JSON.stringify(info, null, 2));
    await ctx.close();
  } finally {
    await owner.cleanup();
  }
});
