type CapturedEmail = { to: string; subject: string; html: string };

/**
 * Starts a local HTTP server that stands in for the Resend API, so the
 * invite email can be inspected without delivering a real message.
 * Resend honours RESEND_BASE_URL, so pointing the app at this server
 * captures the payload instead of sending it.
 */
async function startEmailCaptureServer(): Promise<{
  server: Server;
  baseUrl: string;
  emails: CapturedEmail[];
}> {
  const emails: CapturedEmail[] = [];

  const server = createServer((request, response) => {
    let body = "";
    request.on("data", (chunk) => {
      body += chunk;
    });
    request.on("end", () => {
      try {
        emails.push(JSON.parse(body));
      } catch {
        // Ignore non-JSON payloads.
      }
      response.writeHead(200, { "content-type": "application/json" });
      response.end(JSON.stringify({ id: "captured-email-id" }));
    });
  });

  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const address = server.address();
  const port = typeof address === "object" && address ? address.port : 0;

  return { server, baseUrl: `http://127.0.0.1:${port}`, emails };
}

