import { createServer } from "node:http";
import { appendFileSync, writeFileSync } from "node:fs";

const OUT = process.env.CAPTURE_FILE ?? "/tmp/mail-capture.jsonl";
writeFileSync(OUT, "");

const server = createServer((request, response) => {
  let body = "";
  request.on("data", (chunk) => {
    body += chunk;
  });
  request.on("end", () => {
    try {
      appendFileSync(OUT, JSON.stringify(JSON.parse(body)) + "\n");
    } catch {
      // Ignore non-JSON payloads.
    }
    response.writeHead(200, { "content-type": "application/json" });
    response.end(JSON.stringify({ id: "captured-email-id" }));
  });
});

const port = Number(process.env.CAPTURE_PORT ?? 3999);
server.listen(port, "127.0.0.1", () => {
  console.log(`email capture server listening on http://127.0.0.1:${port}`);
});

