    try {
      const { auth, test: helpers } = await getAuthTestHelpers();
      const { createProject } = await import("../../src/db/queries/projects");

      const victimProject = await createProject({
        organizationId: String(victim.organization.id),
        name: "Secret Project",
        slug: uniqueId("secret"),
      });
      expect(victimProject).toBeTruthy();

      // The attacker has a session, but in a different workspace.
      const attackerHeaders = await helpers.getAuthHeaders({
        userId: attacker.user.id,
      });
      const { auth: authInstance } = await import("../../src/lib/auth");
      const session = await authInstance.api.getSession({ headers: attackerHeaders });
      expect(session?.session?.activeOrganizationId).toBeFalsy();

      // The server function resolves the organization from the session, so a
      // project id alone must not expose another workspace's project.
      const { getProjectServerFn } = await import(
        "../../src/lib/projects-helpers"
      );
      const result = await getProjectServerFn({
        data: { id: victimProject!.id },
      });
      expect(result).toBeFalsy();
    } finally {
      await attacker.cleanup();
      await victim.cleanup();
    }
  });
});

