import { expect, test } from "@playwright/test";
import {
  createPasswordMember,
  createPasswordUser,
  getAuthTestHelpers,
} from "../common";

const PASSWORD = "Password@1";

// The suite talks to a remote Turso database, so every server round trip is
// network bound. Give the UI time to settle before asserting.
const UI_TIMEOUT = 30_000;

test.describe.configure({ timeout: 120_000 });

function uniqueId(prefix: string) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * Tenant isolation is enforced by the server functions, so these tests call
 * the underlying action helpers directly rather than driving the UI. That
 * keeps the assertion on the authorisation boundary itself.
 *
 * The `test.fixme` cases describe the isolation the platform is supposed to
 * guarantee. They are currently failing: the mutation helpers in
 * `src/server/functions` and `src/db/queries` resolve rows by primary key
 * alone, without checking that the row belongs to the caller's workspace.
 * Remove the `test.fixme` marker once the scoping is implemented.
 */
test.describe("tenant isolation", () => {
  test("a collection in another workspace cannot be updated or deleted", async () => {
    const stamp = Date.now();
    const victim = await createPasswordMember({
      email: `victim-${stamp}@example.com`,
      password: PASSWORD,
      name: "Victim",
      organizationName: "Victim Studio",
      organizationSlug: uniqueId("victim"),
    });
    const attacker = await createPasswordUser({
      email: `attacker-${stamp}@example.com`,
      password: PASSWORD,
      name: "Attacker",
    });

    try {
      const { test: helpers } = await getAuthTestHelpers();
      const { createProject } = await import("../../src/db/queries/projects");
      const { createCollection } = await import(
        "../../src/db/queries/collections"
      );
      const { db } = await import("../../src/db");
      const { collections } = await import("../../src/db/schema");
      const { eq } = await import("drizzle-orm");

      const victimProject = await createProject({
        organizationId: String(victim.organization.id),
        name: "Victim Project",
        slug: uniqueId("vp"),
      });
      const victimCollection = await createCollection({
        organizationId: String(victim.organization.id),
        projectId: victimProject!.id,
        name: "Victim Secret",
        slug: "victim-secret",
        description: "Do not touch",
        schema: [{ key: "title", label: "Title", type: "text" }],
      });
      expect(victimCollection).toBeTruthy();

      const { updateCollectionAction, deleteCollectionAction } = await import(
        "../../src/server/functions/collections"
      );

      // The caller's own workspace is not passed to the action, so the action
      // cannot tell that the target belongs to somebody else.
      const updated = await updateCollectionAction(victimCollection!.id, {
        name: "PWNED",
      });
      expect(updated?.name).not.toBe("PWNED");

      await deleteCollectionAction(victimCollection!.id, "victim-secret");

      const [row] = await db
        .select()
        .from(collections)
        .where(eq(collections.id, victimCollection!.id));
      expect(row, "the collection should still exist").toBeTruthy();
      expect(row?.name).toBe("Victim Secret");
    } finally {
      await attacker.cleanup();
      await victim.cleanup();
    }
  });

  test("an item in another workspace cannot be updated or deleted", async () => {
    const stamp = Date.now();
    const victim = await createPasswordMember({
      email: `item-victim-${stamp}@example.com`,
      password: PASSWORD,
      name: "Victim",
      organizationName: "Item Studio",
      organizationSlug: uniqueId("item"),
    });
    const attacker = await createPasswordUser({
      email: `item-attacker-${stamp}@example.com`,
      password: PASSWORD,
      name: "Attacker",
    });

    try {
      const { test: helpers } = await getAuthTestHelpers();
      const { createProject } = await import("../../src/db/queries/projects");
      const { createCollection } = await import(
        "../../src/db/queries/collections"
      );
      const { createItem } = await import("../../src/db/queries/items");

      const victimProject = await createProject({
        organizationId: String(victim.organization.id),
        name: "Victim Project",
        slug: uniqueId("ip"),
      });
      const victimCollection = await createCollection({
        organizationId: String(victim.organization.id),
        projectId: victimProject!.id,
        name: "Victim Items",
        slug: "victim-items",
        schema: [{ key: "title", label: "Title", type: "text" }],
      });
      const victimItem = await createItem(victimCollection!.id, {
        title: "Sensitive",
      });
      expect(victimItem).toBeTruthy();

      const { updateItemAction, deleteItemAction } = await import(
        "../../src/server/functions/items"
      );

      const updated = await updateItemAction(victimItem!.id, "victim-items", {
        title: "PWNED",
      });
      expect(updated?.data?.title).not.toBe("PWNED");

      await deleteItemAction(victimItem!.id, "victim-items");

      const { db } = await import("../../src/db");
      const { collectionItems } = await import("../../src/db/schema");
      const { eq } = await import("drizzle-orm");
      const [row] = await db
        .select()
        .from(collectionItems)
        .where(eq(collectionItems.id, victimItem!.id));
      expect(row, "the item should still exist").toBeTruthy();
      expect(row?.data?.title).toBe("Sensitive");
    } finally {
      await attacker.cleanup();
      await victim.cleanup();
    }
  });

  test("an environment in another workspace cannot be mutated", async () => {
    const stamp = Date.now();
    const victim = await createPasswordMember({
      email: `env-victim-${stamp}@example.com`,
      password: PASSWORD,
      name: "Victim",
      organizationName: "Env Studio",
      organizationSlug: uniqueId("env"),
    });
    const attacker = await createPasswordUser({
      email: `env-attacker-${stamp}@example.com`,
      password: PASSWORD,
      name: "Attacker",
    });

    try {
      const { test: helpers } = await getAuthTestHelpers();
      const { createProject } = await import("../../src/db/queries/projects");
      const { listEnvironments, updateEnvironment } = await import(
        "../../src/db/queries/environments"
      );

      const victimProject = await createProject({
        organizationId: String(victim.organization.id),
        name: "Victim Project",
        slug: uniqueId("ep"),
      });
      const environments = await listEnvironments(victimProject!.id);
      expect(environments.length).toBeGreaterThan(0);

      // The environment helper resolves the caller's organisation, but never
      // checks that the environment's project belongs to it.
      const updated = await updateEnvironment(environments[0].id, {
        name: "PWNED",
      });
      expect(updated?.name).not.toBe("PWNED");
    } finally {
      await attacker.cleanup();
      await victim.cleanup();
    }
  });

  test("a project from another workspace is not readable", async () => {
    const stamp = Date.now();
    const victim = await createPasswordMember({
      email: `proj-victim-${stamp}@example.com`,
      password: PASSWORD,
      name: "Victim",
      organizationName: "Project Studio",
      organizationSlug: uniqueId("proj"),
    });
    const attacker = await createPasswordUser({
      email: `proj-attacker-${stamp}@example.com`,
      password: PASSWORD,
      name: "Attacker",
    });

    try {
      const { test: helpers } = await getAuthTestHelpers();
      const { createProject } = await import("../../src/db/queries/projects");
      const { getProjectById } = await import("../../src/db/queries/projects");

      const victimProject = await createProject({
        organizationId: String(victim.organization.id),
        name: "Secret Project",
        slug: uniqueId("secret"),
      });
      expect(victimProject).toBeTruthy();

      // Reading through the query layer is scoped: the organisation id must
      // match, so a project from another workspace is not returned.
      const crossRead = await getProjectById(
        victimProject!.id,
        String(attacker.user.id),
      );
      expect(crossRead).toBeFalsy();

      const sameWorkspaceRead = await getProjectById(
        victimProject!.id,
        String(victim.organization.id),
      );
      expect(sameWorkspaceRead).toBeTruthy();
    } finally {
      await attacker.cleanup();
      await victim.cleanup();
    }
  });

  test("a collection in another workspace is not listed", async () => {
    const stamp = Date.now();
    const victim = await createPasswordMember({
      email: `list-victim-${stamp}@example.com`,
      password: PASSWORD,
      name: "Victim",
      organizationName: "List Studio",
      organizationSlug: uniqueId("list"),
    });
    const attacker = await createPasswordUser({
      email: `list-attacker-${stamp}@example.com`,
      password: PASSWORD,
      name: "Attacker",
    });

    try {
      const { createProject } = await import("../../src/db/queries/projects");
      const { createCollection, listCollections } = await import(
        "../../src/db/queries/collections"
      );

      const victimProject = await createProject({
        organizationId: String(victim.organization.id),
        name: "Victim Project",
        slug: uniqueId("lp"),
      });
      await createCollection({
        organizationId: String(victim.organization.id),
        projectId: victimProject!.id,
        name: "Victim Secret",
        slug: "victim-secret",
        schema: [{ key: "title", label: "Title", type: "text" }],
      });

      // Listing is scoped by organisation, so the attacker's own (empty)
      // workspace never returns the victim's collection.
      const attackerOrg = await import("../../src/db/queries/projects");
      void attackerOrg;
      const attackerList = await listCollections({
        organizationId: "attacker-workspace-that-does-not-exist",
      });
      expect(attackerList.items).toHaveLength(0);
    } finally {
      await attacker.cleanup();
      await victim.cleanup();
    }
  });
});

