export function serverFnUrl(file: string, exportName: string) {
  const payload = JSON.stringify({
    file: `${file}?tss-serverfn-split`,
    export: exportName,
  });
  return `/_serverFn/${Buffer.from(payload).toString("base64url")}`;
}

