import { test } from "@playwright/test";
import { createPasswordMember, getAuthTestHelpers } from "../common";

test("final sidebar", async ({ context, browser }) => {
  const stamp = Date.now();
  const owner = await createPasswordMember({
    email: `fin-${stamp}@example.com`, password: "Password@1", name: "Owner",
    organizationName: `Studio ${stamp}`, organizationSlug: `studio-${stamp}`,
  });
  try {
    const { test: helpers } = await getAuthTestHelpers();
    for (const scheme of ["light", "dark"] as const) {
      const ctx = await browser.newContext({ viewport: { width: 1280, height: 860 }, colorScheme: scheme });
      await ctx.addCookies(await helpers.getCookies({ userId: owner.user.id, domain: "127.0.0.1" }));
      const p = await ctx.newPage();
      await p.goto("/dashboard");
      await p.waitForTimeout(12000);
      await p.screenshot({ path: `/tmp/shots/final-desktop-${scheme}.png` });
      console.log(`DESKTOP[${scheme}]`, JSON.stringify(await p.evaluate(() => {
        const sb = document.querySelector('[data-slot="sidebar"]');
        const wrap = document.querySelector('[data-slot="sidebar-wrapper"]');
        return { sidebar: sb ? getComputedStyle(sb).backgroundColor : null, content: wrap ? getComputedStyle(wrap).backgroundColor : null };
      })));
      await ctx.close();
    }
    // mobile
    const mctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
    await mctx.addCookies(await helpers.getCookies({ userId: owner.user.id, domain: "127.0.0.1" }));
    const mp = await mctx.newPage();
    await mp.goto("/dashboard");
    await mp.waitForTimeout(12000);
    await mp.locator('[data-slot="sidebar-trigger"]').first().click();
    await mp.waitForTimeout(2000);
    await mp.screenshot({ path: "/tmp/shots/final-mobile-sheet.png" });
    console.log("MOBILE drawer bg:", await mp.evaluate(() => {
      const el = document.querySelector('[data-mobile="true"]');
      return el ? getComputedStyle(el).backgroundColor : "not found";
    }));
    await mctx.close();
  } finally {
    await owner.cleanup();
  }
});
EOF
