import { readdir, stat } from "node:fs/promises";
import { extname, join } from "node:path";
import { readJsonFile, relativeSafe } from "./file-utils";
import type { PullResponse, SyncedCollection } from "./types";

export async function loadCollectionsInput(filePath: string, collectionId?: string) {
  const stats = await stat(filePath).catch(() => null);

  if (!stats) {
    throw new Error(
      `Collections source not found: ${relativeSafe(filePath)}. Run pull first or create mini.collections.json.`,
    );
  }

  const collections = stats.isDirectory()
    ? await loadCollectionsFromDirectory(filePath)
    : await loadCollectionsFromFile(filePath);

  const filtered = collectionId
    ? collections.filter((collection) => collection.id === collectionId)
    : collections;

  if (collectionId && !filtered.length) {
    throw new Error(
      `Collection ${collectionId} was not found in ${relativeSafe(filePath)}.`,
    );
  }

  return filtered;
}

async function loadCollectionsFromDirectory(directoryPath: string) {
  const entries = await readdir(directoryPath, { withFileTypes: true });
  const allCollections: SyncedCollection[] = [];

  for (const entry of entries) {
    if (!entry.isFile() || extname(entry.name) !== ".json") {
      continue;
    }

    const filePath = join(directoryPath, entry.name);
    const fileCollections = await loadCollectionsFromFile(filePath);
    allCollections.push(...fileCollections);
  }

  return deduplicateCollections(allCollections);
}

function deduplicateCollections(collections: SyncedCollection[]) {
  const bySlug = new Map<string, SyncedCollection>();

  for (const collection of collections) {
    const existing = bySlug.get(collection.slug);

    if (!existing || (!existing.id && collection.id)) {
      bySlug.set(collection.slug, collection);
    }
  }

  return Array.from(bySlug.values());
}

async function loadCollectionsFromFile(filePath: string) {
  const json = await readJsonFile<
    PullResponse | { collections: SyncedCollection[] } | SyncedCollection
  >(filePath);

  if (Array.isArray((json as { collections?: unknown }).collections)) {
    return normalizeCollections(
      (json as PullResponse | { collections: SyncedCollection[] }).collections,
    );
  }

  if (isCollectionShape(json)) {
    return normalizeCollections([json]);
  }

  throw new Error(`Invalid collections file: ${relativeSafe(filePath)}.`);
}

import { Link, createFileRoute } from "@tanstack/react-router";
import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { updateCollectionServerFn } from "@/lib/collections-helpers";
import { RESERVED_FIELD_PREFIX, isReservedFieldKey } from "@/lib/collections-system-fields";
import { collectionSchemaQueryOptions } from "@/lib/queries";
import { Skeleton } from "@workspace/ui/components/skeleton";
import {
  ArrowLeft,
  Plus,
  Trash2,
  Save,
  CheckCircle,
  AlertCircle,
} from "lucide-react";

type SchemaField = {
  _id: string;
  key: string;
  label: string;
  type: "text" | "url" | "number" | "boolean" | "date";
};

let nextId = 0;
function stableId() {
  return `field-${++nextId}`;
}

export const Route = createFileRoute("/dashboard/collections/$name/schema")({
  validateSearch: (search: Record<string, unknown>) => ({
    projectId:
      typeof search.projectId === "string" && search.projectId.length > 0
        ? search.projectId
        : undefined,
  }),
  component: CollectionSchemaPage,
});

function CollectionSchemaPage() {
  const { name } = Route.useParams();
  const search = Route.useSearch();
  const queryClient = useQueryClient();
  const schemaQuery = useQuery(collectionSchemaQueryOptions(name, search.projectId));

  function invalidate() {
    void queryClient.invalidateQueries({
      queryKey: ["collection-schema", name],
    });
    void queryClient.invalidateQueries({
      queryKey: ["collection-page", name],
    });
  }

  if (schemaQuery.isLoading) {
    return <SchemaPageSkeleton />;
  }

  if (!schemaQuery.data) {
    return (
      <section className="space-y-6">
        <p className="text-sm text-stone-500">Collection not found.</p>
      </section>
    );
  }

  return (
    <SchemaEditor
      collection={schemaQuery.data.collection}
      projectId={search.projectId}
      onSaved={invalidate}
    />
  );
}

function SchemaEditor(props: {
  collection: {
    id: string;
    name: string;
    slug: string;
    schema: Array<{
      key: string;
      label: string;
      type: "text" | "url" | "number" | "boolean" | "date";
    }>;
  };
  projectId?: string;
  onSaved: () => void;
}) {
  const { collection, projectId, onSaved } = props;
  const [fields, setFields] = useState<SchemaField[]>(() => {
    const source = collection.schema.length
      ? collection.schema
      : [{ key: "title", label: "Title", type: "text" as const }];
    return source.map((f: (typeof source)[number]) => ({
      ...f,
      _id: stableId(),
    }));
  });
  const [pending, setPending] = useState(false);
  const [message, setMessage] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  function updateField(index: number, patch: Partial<(typeof fields)[number]>) {
    setFields((current) =>
      current.map((field, currentIndex) =>
        currentIndex === index ? { ...field, ...patch } : field,
      ),
    );
  }

  async function handleSave() {
    const reservedField = fields.find((field) => isReservedFieldKey(field.key));

    if (reservedField) {
      setMessage({
        type: "error",
        text: `Field key '${reservedField.key}' is reserved. Keys starting with '${RESERVED_FIELD_PREFIX}' are reserved for system fields.`,
      });
      return;
    }

    setPending(true);
    setMessage(null);

    const updated = await updateCollectionServerFn({
      data: {
        id: collection.id,
        schema: fields.map(({ _id, ...rest }) => rest),
      },
    });

    setPending(false);

    if (updated) {
      setMessage({ type: "success", text: "Schema saved successfully." });
      onSaved();
    } else {
      setMessage({
        type: "error",
        text: "Unable to save schema. Please try again.",
      });
    }
  }

  return (
    <section className="space-y-6">
      <div>
        <Link
          to="/dashboard/collections/$name"
          params={{ name: collection.slug }}
          search={{ page: 1, projectId, env: undefined }}
          className="inline-flex items-center gap-1.5 text-sm text-stone-500 transition hover:text-stone-900"
        >
          <ArrowLeft className="h-4 w-4" />
          {collection.name}
        </Link>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-semibold tracking-tight">Edit schema</h2>
          <p className="mt-1 text-sm text-stone-500">
            Define the fields that make up each item in{" "}
            <span className="font-medium text-stone-700">
              {collection.name}
            </span>
            .
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={() =>
              setFields((current) => [
                ...current,
